    local State = {
        OriginalDescription = nil,
        Favorites = {}
    }

    -- [[ FILE SYSTEM MANAGER ]]
    local function LoadFavorites()
        if isfile and isfile(CloneConfig.FileName) then
            local success, result = pcall(function()
                return HttpService:JSONDecode(readfile(CloneConfig.FileName))
            end)
            if success and type(result) == "table" then
                State.Favorites = result
            end
        end
    end

    local function SaveFavorites()
        if writefile then
            local json = HttpService:JSONEncode(State.Favorites)
            writefile(CloneConfig.FileName, json)
        end
    end
    
    -- Load initial data
    LoadFavorites()

    -- [[ CORE LOGIC ]]
    
    -- Simpan penampilan asli saat script dimuat pertama kali
    pcall(function()
        if LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("Humanoid") then
            State.OriginalDescription = LocalPlayer.Character.Humanoid:GetAppliedDescription()
        end
    end)

    local function Notify(title, text)
        StarterGui:SetCore("SendNotification", {
            Title = title,
            Text = text,
            Duration = 3
        })
    end

    local function ApplyAvatar(userId)
        userId = tonumber(userId)
        if not userId then return end

        task.spawn(function()
            local character = LocalPlayer.Character
            local humanoid = character and character:FindFirstChild("Humanoid")
            
            if not humanoid then return end

            -- Simpan original jika belum ada
            if not State.OriginalDescription then
                State.OriginalDescription = humanoid:GetAppliedDescription()
            end

            Notify("Clone Avatar", "Fetching assets...")

            local success, desc = pcall(function()
                return Players:GetHumanoidDescriptionFromUserId(userId)
            end)

            if success and desc then
                humanoid:ApplyDescription(desc)
                Notify("Success", "Avatar cloned successfully!")
            else
                Notify("Error", "Failed to load avatar. ID invalid?")
            end
        end)
    end

    local function ResetAvatar()
        if State.OriginalDescription and LocalPlayer.Character then
            local hum = LocalPlayer.Character:FindFirstChild("Humanoid")
            if hum then
                hum:ApplyDescription(State.OriginalDescription)
                Notify("Reset", "Avatar restored to original.")
            end
        else
            Notify("Error", "No original avatar saved.")
        end
    end

    local function GetIdFromInput(input)
        if tonumber(input) then
            return tonumber(input)
        else
            -- Try to get ID from username
            local success, id = pcall(function()
                return Players:GetUserIdFromNameAsync(input)
            end)
            if success then return id end
        end
        return nil
    end

