        -- [[ FAVORITES LOGIC ]]
        local function RefreshFavorites()
            -- Clear existing
            for _, v in pairs(FavPage:GetChildren()) do
                if v:IsA("Frame") then v:Destroy() end
            end
            
            for i, fav in ipairs(State.Favorites) do
                local Item = Instance.new("Frame", FavPage)
                Item.Size = UDim2.new(1, 0, 0, 50)
                Item.BackgroundColor3 = CloneConfig.Theme.ItemBG
                
                local ItemCorner = Instance.new("UICorner", Item)
                ItemCorner.CornerRadius = UDim.new(0, 6)
                
                -- Avatar Image (Headshot)
                local Img = Instance.new("ImageLabel", Item)
                Img.Size = UDim2.new(0, 35, 0, 35)
                Img.Position = UDim2.new(0, 8, 0.5, -17.5)
                Img.BackgroundColor3 = Color3.fromRGB(40, 40, 40)
                Img.Image = "rbxthumb://type=AvatarHeadShot&id=" .. fav.id .. "&w=150&h=150"
                
                local ImgCorner = Instance.new("UICorner", Img)
                ImgCorner.CornerRadius = UDim.new(1, 0)
                
                -- Info
                local NameLbl = Instance.new("TextLabel", Item)
                NameLbl.Position = UDim2.new(0, 55, 0, 8)
                NameLbl.Size = UDim2.new(0, 150, 0, 15)
                NameLbl.BackgroundTransparency = 1
                NameLbl.Text = fav.name
                NameLbl.TextColor3 = Color3.new(1,1,1)
                NameLbl.Font = Enum.Font.GothamBold
                NameLbl.TextSize = 12
                NameLbl.TextXAlignment = Enum.TextXAlignment.Left
                
                local IdLbl = Instance.new("TextLabel", Item)
                IdLbl.Position = UDim2.new(0, 55, 0, 25)
                IdLbl.Size = UDim2.new(0, 150, 0, 15)
                IdLbl.BackgroundTransparency = 1
                IdLbl.Text = "ID: " .. fav.id
                IdLbl.TextColor3 = CloneConfig.Theme.SubText
                IdLbl.Font = Enum.Font.Gotham
                IdLbl.TextSize = 10
                IdLbl.TextXAlignment = Enum.TextXAlignment.Left
                
                -- Load Button (Invisible over text)
                local LoadBtn = Instance.new("TextButton", Item)
                LoadBtn.Size = UDim2.new(0.7, 0, 1, 0)
                LoadBtn.BackgroundTransparency = 1
                LoadBtn.Text = ""
                LoadBtn.MouseButton1Click:Connect(function()
                    ApplyAvatar(fav.id)
                end)
                
                -- Delete Button
                local DelBtn = Instance.new("TextButton", Item)
                DelBtn.Size = UDim2.new(0, 25, 0, 25)
                DelBtn.Position = UDim2.new(1, -35, 0.5, -12.5)
                DelBtn.BackgroundColor3 = CloneConfig.Theme.Random
                DelBtn.Text = "×"
                DelBtn.TextColor3 = Color3.new(1,1,1)
                DelBtn.Font = Enum.Font.GothamBold
                
                local DelCorner = Instance.new("UICorner", DelBtn)
                DelCorner.CornerRadius = UDim.new(0, 4)
                
                DelBtn.MouseButton1Click:Connect(function()
                    table.remove(State.Favorites, i)
                    SaveFavorites()
                    RefreshFavorites()
                end)
            end
        end

        -- [[ BUTTON EVENTS ]]
        
