            ChangerBtn.BackgroundTransparency = 1
            ChangerBtn.BackgroundColor3 = CloneConfig.Theme.ItemBG
            ChangerBtn.TextColor3 = CloneConfig.Theme.SubText
        end)
        
        -- Copy Logic
        CopyBtn.MouseButton1Click:Connect(function()
            local input = InputBox.Text
            if input == "" then Notify("Warning", "Please enter a username or ID") return end
            
            local id = GetIdFromInput(input)
            if id then
                ApplyAvatar(id)
            else
                Notify("Error", "User not found")
            end
        end)
        
        -- Add to Favs
        AddFavBtn.MouseButton1Click:Connect(function()
            local input = InputBox.Text
            local id = GetIdFromInput(input)
            
            if id then
                -- Get Name
                local name = "Unknown"
                pcall(function() name = Players:GetNameFromUserIdAsync(id) end)
                
                -- Check duplicate
                for _, fav in ipairs(State.Favorites) do
                    if fav.id == id then Notify("Info", "Already in favorites") return end
                end
                
                table.insert(State.Favorites, {name = name, id = id})
                SaveFavorites()
                Notify("Success", "Added to favorites!")
            else
                Notify("Error", "Invalid ID/User to save")
            end
        end)
        
        -- Reset
        ResetBtn.MouseButton1Click:Connect(ResetAvatar)
        
        -- Random Player
        RandomBtn.MouseButton1Click:Connect(function()
            local playerList = Players:GetPlayers()
            if #playerList > 1 then
                local randomPlayer = playerList[math.random(1, #playerList)]
                -- Hindari diri sendiri
                if randomPlayer == LocalPlayer then
                    randomPlayer = playerList[math.random(1, #playerList)]
                end
                
                InputBox.Text = randomPlayer.Name
                ApplyAvatar(randomPlayer.UserId)
            else
                Notify("Info", "Not enough players to random")
            end
        end)

        -- Draggable
        local function makeDraggable(frame)
            local dragging, dragInput, dragStart, startPos
            frame.InputBegan:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                    dragging = true
                    dragStart = input.Position
                    startPos = frame.Position
                    
                    input.Changed:Connect(function()
                        if input.UserInputState == Enum.UserInputState.End then dragging = false end
                    end)
                end
            end)
            frame.InputChanged:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
                    dragInput = input
                end
            end)
            UserInputService.InputChanged:Connect(function(input)
                if input == dragInput and dragging then
                    local delta = input.Position - dragStart
                    frame.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
                end
            end)
        end
        
        makeDraggable(MainFrame)
    end

